cmd:
cat > /app/hierarchical_model.stan << 'EOF'
data {
  int<lower=1> J;                    // number of groups
  array[J] int<lower=0> y;           // successes in each group
  array[J] int<lower=1> n;           // trials in each group
}
parameters {
  vector<lower=0, upper=1>[J] theta; // group-specific probabilities
  real<lower=0> alpha;               // beta-distribution shape 1
  real<lower=0> beta;                // beta-distribution shape 2
}
model {
  // likelihood: y_i ~ Binomial(n_i, theta_i)
  y ~ binomial(n, theta);

  // hyper-prior: theta_i ~ Beta(alpha, beta)
  theta ~ beta(alpha, beta);

  // prior on (alpha, beta) proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);
}
EOF
echo written; cat /app/hierarchical_model.stan
